// Small, material-coloured drawings shared by category, subtype and item views.
// Explicit fills keep metal, glass, paper and food from inheriting one category colour.
const art = (body, stroke='#56616a') => `<g stroke="${stroke}" stroke-width="1.25">${body}</g>`;
const rect = (x,y,w,h,fill,rx=1) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${fill}"/>`;
const circle = (x,y,r,fill) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}"/>`;
const line = (d,stroke) => `<path d="${d}" fill="none"${stroke ? ` stroke="${stroke}"` : ''}/>`;
const shape = (d,fill) => `<path d="${d}" fill="${fill}"/>`;
