// Update the embedded components too: small secondary objects are not recoloured
// as a single flat silhouette, and subtype compositions keep their identities.
const replacements = Object.entries({...REFINED_ART,...REALISTIC_ART})
  .filter(([key])=>SHAPES[key]).map(([key,value])=>[SHAPES[key],value])
  .sort((a,b)=>b[0].length-a[0].length);
for (const entries of Object.values(SUBTYPE_ART)) for (const sub of Object.keys(entries)) {
  const originals=[];
  for (const [oldArt,newArt] of replacements) {
    const token=`__ART_${originals.length}__`;
    if(entries[sub].includes(oldArt)){entries[sub]=entries[sub].split(oldArt).join(token);originals.push([token,newArt]);}
  }
  for(const [token,newArt] of originals) entries[sub]=entries[sub].split(token).join(newArt);
}
Object.assign(SHAPES,REFINED_ART,REALISTIC_ART);

